<script setup>
import {changeCaptionSource} from '../caption-source.mjs';
function selectVideoSource(asset,kind='edit'){return changeCaptionSource({draft:d,save},asset.id,kind);}
import {computed,inject,ref,watch} from 'vue';
import CaptionEditor from '../components/CaptionEditor.vue';
import {openCaptionSession} from '../caption-edit-session.mjs';import I from '../components/Icon.vue';import AssetPicker from '../components/AssetPicker.vue';import MediaPreview from '../components/MediaPreview.vue';import {call} from '../api';
import WorkflowMode from '../components/WorkflowMode.vue';
import {runTextAction} from '../text-action.mjs';
import {confirmCopyAction} from '../copy-confirmation-action.mjs';
import {runSpeechAction} from '../speech-action.mjs';
import {runAvatarAction} from '../avatar-action.mjs';
import {runExtractAction} from '../extract-action.mjs';
import LegacyVoicePanel from '../components/LegacyVoicePanel.vue';
import {promptsFor,resolvePrompt} from '../../server/prompt-catalog.mjs';
import DropdownSelect from '../components/DropdownSelect.vue';
import WordLimit from '../components/WordLimit.vue';
import WorkflowStatus from '../components/WorkflowStatus.vue';
const {draft:d,state,busy,act,notify,newTask,navigate,showDialog,save,startWorkflow,workflowLocked}=inject('studio');const picker=ref(null),captionOpen=ref(false),captionSession=ref(null);
watch(()=>[d.value.id,d.value.edit.sourceId||d.value.video.assetId],()=>{captionOpen.value=false;captionSession.value=null;});
function editCaptions(){if(!d.value.edit.captions.length)return openStep(4);captionSession.value=openCaptionSession(captionSession.value,d.value);captionOpen.value=true;}
async function importCaption(asset){const rows=await act('导入字幕',async()=>call('importCaptions',{text:await call('assetText',{id:asset.id})}));if(rows){d.value.edit.captions=rows;d.value.edit.subtitlesEnabled=true;await save();editCaptions();}}

const rewritePrompt=computed(()=>resolvePrompt('rewrite',state.value,d.value.template));
const rewriteTemplate=computed({get:()=>rewritePrompt.value.id,set:id=>d.value.template=id});
const rewriteOptions=computed(()=>promptsFor('rewrite',state.value).map(p=>({value:p.id,label:p.name})));
function choose(kind,assign){picker.value={kind,assign};}
function selectBgm(asset){Object.assign(d.value.edit,{bgmId:asset.id,bgmSource:'upload',bgmResourceId:''});}
async function selected(asset){const assign=picker.value.assign;picker.value=null;try{await assign(asset);}catch(error){notify(error.message,'error');}}
function text(kind){return runTextAction({draft:d,state,save,act,call,notify,showDialog,showLegal:text=>showDialog('文案检查建议',text)},kind);}
async function generate(action,group,key){if(action==='speech')return runSpeechAction({draft:d,state,save,act,call,notify});if(action==='avatar')return runAvatarAction({draft:d,state,save,act,call,notify});const id=d.value.id;const r=await act('生成产物',()=>call(action,{id}));if(r&&!r.stale&&d.value.id===id){d.value[group][key]=r.id;notify('已生成并校验实际媒体','success');}}
function extract(){return runExtractAction({draft:d,save,act,call,notify});}
function useCopy(){return confirmCopyAction({draft:d,save,act,call,notify,startWorkflow});}
async function pack(){const r=await act('导出发布包',()=>call('exportPackage',{id:d.value.id}));if(r){d.value.publish.recordId=r.id;showDialog('发布包已导出',r.directory+'\n尚未上传平台。');}}
function openStep(step){d.value.step=step;navigate('new');}
</script>
<template><section class="legacy-page"><div class="legacy-toolbar"><div></div><WorkflowMode/><button @click="newTask">开始新任务</button></div><WorkflowStatus/><div class="legacy-grid" :inert="workflowLocked"><div class="legacy-col"><article class="legacy-card"><header><span><I name="Link"/></span><h3>1. 学习对标</h3><button class="text-button" @click="openStep(0)">展开</button></header><div class="legacy-card-body"><div class="segmented"><button v-for="[id,name] in [['extract','提取文案'],['brain','IP大脑'],['topic','爆款选题'],['marketing','营销文案']]" :key="id" @click="d.tab=id;openStep(0)">{{name}}</button></div><label>视频链接<div class="inline"><input v-model="d.sourceUrl" placeholder="输入视频分享链接"/><button class="primary" :disabled="!!busy" @click="extract">提取文案</button></div></label><label>原文案<textarea v-model="d.sourceText" class="legacy-source"></textarea></label></div></article><article class="legacy-card"><header><span><I name="PencilLine"/></span><h3>2. 改写文案</h3></header><div class="legacy-card-body"><div class="two-fields legacy-rewrite-controls"><label>写作提示词<DropdownSelect v-model="rewriteTemplate" aria-label="旧工作流写作提示词" :options="rewriteOptions"/></label><WordLimit v-model="d.wordLimit" label="字数"/></div><p v-if="rewritePrompt.source?.kind==='reference-visible'" class="legacy-prompt-note">此模板要求字数接近原文（当前 {{d.sourceText.length}} 字），请核对改写后的信息与表达。</p><div class="two-fields"><button class="primary full" :disabled="!!busy" @click="text('rewrite')">改写文案</button><button class="warm full" :disabled="!!busy" @click="text('legal')">AI法务</button></div><label>改写内容<textarea v-model="d.rewrite" class="legacy-copy" aria-label="旧工作流改写内容"></textarea></label><button class="secondary full" @click="useCopy">{{['auto','background'].includes(d.mode)?'一键处理后续所有步骤':'确认为最终文案'}}</button></div></article></div><div class="legacy-col"><LegacyVoicePanel @generate="generate('speech','voice','audioId')" @choose="(kind,assign,title)=>choose(kind,assign,title)"/><article class="legacy-card"><header><span><I name="User"/></span><h3>4. 视频生成</h3><button class="text-button" @click="navigate('avatars')">上传形象</button></header><div class="legacy-card-body"><div class="segmented"><button :class="{active:d.video.mode==='single'}" @click="d.video.mode='single'">单形象</button><button :class="{active:d.video.mode==='multi'}" @click="openStep(3)">多镜头</button></div><button class="secondary full" @click="d.video.mode='story';openStep(3)">非口播创作 · 分集与分镜</button><label>选择形象<select v-model="d.video.avatarId"><option value="">请选择形象</option><option v-for="a in state.avatars" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>驱动音频<select v-model="d.video.audioId"><option value="">使用生成的声音</option><option v-for="a in state.assets.filter(a=>a.type==='audio')" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>模型版本<select v-model="d.video.model"><option value="v2">高清模型V2</option><option value="v1">经典模型V1</option></select></label><button class="primary full" :disabled="!!busy" @click="generate('avatar','video','assetId')">生成视频</button><button class="secondary full" @click="choose('video',a=>selectVideoSource(a,'video'))">导入已有视频</button><MediaPreview :id="d.video.assetId" title="暂无数字人视频"/></div></article></div><div class="legacy-col legacy-right"><article class="legacy-card"><header><span><I name="Scissors"/></span><h3>5. 一键成片</h3><button class="text-button" @click="openStep(4)">详细剪辑</button></header><div class="legacy-render"><div><label>视频源<button class="upload-zone" @click="choose('video',selectVideoSource)">{{state.assets.find(a=>a.id===(d.edit.sourceId||d.video.assetId))?.name||'自动使用上一步数字人视频，或手动选择'}}</button></label><h3>字幕设置</h3><label class="check-row"><input v-model="d.edit.subtitlesEnabled" type="checkbox"/>启用字幕 <button @click="openStep(4)">字幕设置</button></label><h3>混剪（画中画）素材 · 背景音乐</h3><label class="check-row"><input v-model="d.edit.pipEnabled" type="checkbox"/>启用画中画<button @click="choose('visual',a=>{d.edit.pipId=a.id;d.edit.pipMode='continuous'})">选择</button></label><label class="check-row"><input v-model="d.edit.bgmEnabled" type="checkbox"/>启用BGM<button @click="choose('audio',selectBgm)">选择</button></label><div class="two-fields"><label>人声音量 {{d.edit.volume}}<input v-model.number="d.edit.volume" type="range" min="0" max="3" step="0.05"/></label><label>BGM音量 {{d.edit.bgmVolume}}<input v-model.number="d.edit.bgmVolume" type="range" min="0" max="1" step="0.05"/></label></div><h3>编辑字幕与视频</h3><button class="secondary full" :disabled="!!busy" @click="editCaptions">编辑字幕</button><button class="primary full" :disabled="!!busy" @click="generate('render','edit','resultId')">剪辑视频</button></div><div class="legacy-video"><h3>视频预览</h3><MediaPreview :id="d.edit.resultId||d.edit.sourceId||d.video.assetId" title="暂无预览视频"/></div></div></article><div class="legacy-bottom"><article class="legacy-card"><header><span><I name="Image"/></span><h3>6. 标题封面</h3></header><div class="legacy-card-body"><label>标题<div class="inline"><input v-model="d.cover.title" placeholder="输入视频标题"/><button :disabled="!!busy" @click="text('title')">一键生成</button></div></label><button class="secondary full" @click="openStep(5)">打开封面编辑器</button><MediaPreview v-if="d.cover.assetId" :id="d.cover.assetId" type="image"/></div></article><article class="legacy-card"><header><span><I name="Rocket"/></span><h3>7. 视频发布</h3></header><div class="legacy-card-body"><label>作品标题<input v-model="d.publish.title"/></label><label>作品描述<textarea v-model="d.publish.description"></textarea></label><button class="primary full" :disabled="!!busy" @click="pack">导出发布包</button><button class="secondary full" @click="openStep(6)">发布配置</button></div></article></div></div></div><CaptionEditor v-if="captionOpen" :session="captionSession" auxiliary-tools @close="captionOpen=false" @import="choose('text',importCaption)"/><AssetPicker v-if="picker" :kind="picker.kind" @close="picker=null" @select="selected"/></section></template>
